+// API keys and the audit log. Keys live in `apiKeys` ({ key, name, role });
+// every request that changes data leaves one entry in `audit`.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** The roles, from least to most allowed. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for `key`, or null if there is none. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  const wanted = digest(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (timingSafeEqual(digest(k.key), wanted) && ROLES.includes(k.role)) found = k;
+  }
+  return found;
+}
+
+/** Appends an audit entry { at, keyName, method, path, status }. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  const entry = { at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
