+// Who may call what. Requests carry `Authorization: Bearer <key>`; the key's
+// role decides which routes it may use:
+//   viewer   reads only (GET), except the audit log
+//   cook     also cooks, records waste, logs temperatures and counts stock
+//   manager  everything
+import { AppError } from "../errors.js";
+import { findKey } from "../domain/access.js";
+
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+const MANAGER_ONLY_READS = new Set(["GET /audit"]);
+
+/** The API key record for the request's bearer token; throws `unauthorized` without one. */
+export function authenticate(store, headers) {
+  const raw = headers.authorization ?? headers.Authorization;
+  const m = typeof raw === "string" ? /^Bearer\s+(\S+)\s*$/i.exec(raw) : null;
+  const key = m ? findKey(store, m[1]) : null;
+  if (!key) throw new AppError("unauthorized");
+  return key;
+}
+
+/** Whether `role` may call the route `method pattern`. */
+export function allowed(role, method, pattern) {
+  const route = `${method} ${pattern}`;
+  if (role === "manager") return true;
+  if (MANAGER_ONLY_READS.has(route)) return false;
+  if (method === "GET") return true;
+  return role === "cook" && COOK_ROUTES.has(route);
+}
+
+/** Throws `forbidden` unless `key` may call the route. */
+export function authorize(key, method, pattern, path) {
+  if (!allowed(key.role, method, pattern)) throw new AppError("forbidden", { role: key.role, method, path });
+}
