+++ b/tests/auth.test.js
@@ -0,0 +1,63 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, bearer, NOW } from "./helpers.js";
+import { CURRENT_VERSION, migrate } from "../src/db/migrations.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { handle, store } = app();
+  for (const headers of [{}, { authorization: "Bearer nope" }, { authorization: "Basic abc" }]) {
+    const res = await handle({ path: "/items", headers });
+    assert.equal(res.status, 401);
+    assert.equal(res.body.error.code, "unauthorized");
+    assert.ok(res.body.error.message);
+  }
+  const post = await handle({ method: "POST", path: "/jobs/nightly", headers: {} });
+  assert.equal(post.status, 401);
+  assert.equal(store.data.audit.length, 0);
+});
+
+test("viewers may only read", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ path: "/items", headers: bearer("viewer") })).status, 200);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: bearer("viewer"), body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+});
+
+test("cooks cook, waste, log temperatures and count stock, nothing else", async () => {
+  const { handle } = app();
+  const cook = bearer("cook");
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: cook, body: { qty: 1, reason: "dropped" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 3 } })).status, 201);
+  const take = await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } });
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.body.id}/counts`, headers: cook, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.body.id}/finish`, headers: cook })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders/1/cancel", headers: cook })).status, 403);
+  assert.equal((await handle({ method: "PUT", path: "/items/1/allergens", headers: cook, body: { allergens: [] } })).status, 403);
+});
+
+test("changes are audited and only managers read the audit, newest first", async () => {
+  const { handle } = app();
+  await handle({ method: "POST", path: "/recipes/1/cook", headers: bearer("cook"), body: { portions: 1 } });
+  await handle({ method: "POST", path: "/recipes/2/cook", headers: bearer("cook"), body: { portions: 100 } });
+  await handle({ method: "POST", path: "/jobs/nightly", headers: bearer("viewer") });
+  await handle({ path: "/items", headers: bearer("viewer") });
+  assert.equal((await handle({ path: "/audit", headers: bearer("viewer") })).status, 403);
+  assert.equal((await handle({ path: "/audit", headers: bearer("cook") })).status, 403);
+  const res = await handle({ path: "/audit" });
+  assert.equal(res.status, 200);
+  const at = new Date(NOW).toISOString();
+  assert.deepEqual(res.body, [
+    { at, keyName: "front desk", method: "POST", path: "/jobs/nightly", status: 403 },
+    { at, keyName: "line cook", method: "POST", path: "/recipes/2/cook", status: 409 },
+    { at, keyName: "line cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+  ]);
+});
+
+test("schema 2 files get empty keys and audit", () => {
+  const data = migrate({ schemaVersion: 2, seq: {}, items: [], batches: [], movements: [] });
+  assert.equal(data.schemaVersion, CURRENT_VERSION);
+  assert.deepEqual(data.apiKeys, []);
+  assert.deepEqual(data.audit, []);
+});
